UPDATE workflow_modules
SET configuration_schema = $json${"fields":[{"key":"method","label":"Method","type":"select","required":true,"default":"POST","options":["GET","POST","PUT","PATCH","DELETE"]},{"key":"url","label":"URL","type":"url","required":true,"placeholder":"https://api.example.com/action"},{"key":"body","label":"JSON body","type":"textarea","required":false,"placeholder":"{ \"key\": \"value\" }"},{"key":"secretId","label":"Credential","type":"secret","required":false},{"key":"secretPlacement","label":"Credential placement","type":"select","required":false,"default":"bearer","options":["bearer","header"]},{"key":"secretHeader","label":"Header name","type":"text","required":false,"default":"Authorization","placeholder":"Authorization"},{"key":"timeoutSeconds","label":"Timeout (seconds)","type":"number","required":true,"default":60,"min":1,"max":3600}]}$json$::jsonb
WHERE module_id='builtin.http' AND module_version='0.1.0';
